+
+  expect(Object.keys(TEAM_ALIASES).length).toBeGreaterThan(0);
+  const validTeamNames = new Set(ALL_CFB_TEAMS);
+  for (const teamName of Object.values(TEAM_ALIASES)) {
+    expect(validTeamNames.has(teamName)).toBe(true);
+  }
+});

